function draw(ctx, state, t) {
  var w = state.w, h = state.h, mag = state.mag, keep = Math.round(state.keep);
  var n = 16, xs = [], rec = [], i, ax, amax = 0, step, q, err = 0, cnt = 0;
  for (i = 0; i < n; i++) xs[i] = i === 7 ? mag : Math.sin(i * 1.7 + 0.4) * 0.35;
  for (i = 0; i < n; i++) {
    ax = xs[i] < 0 ? -xs[i] : xs[i];
