  }
  if (amax < 1e-6) amax = 1e-6;
  step = amax / 127;
  for (i = 0; i < n; i++) {
    ax = xs[i] < 0 ? -xs[i] : xs[i];
    if (keep === 1 && ax > 6) rec[i] = xs[i];
    else {
      q = Math.round(xs[i] / step);
      if (q > 127) q = 127;
      if (q < -127) q = -127;
      rec[i] = q * step;
      err += (rec[i] - xs[i]) * (rec[i] - xs[i]);
      cnt += 1;
    }
  }
  err = cnt ? Math.sqrt(err / cnt) : 0;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  function Y(v) {
    if (v > 0.55) v = 0.55;
