  }
  ctx.strokeStyle = "#e0d5c6";
  ctx.beginPath();
  ctx.moveTo(12, Y(0));
  ctx.lineTo(w - 12, Y(0));
  ctx.stroke();
  var gap = (w - 36) / n;
  for (i = 0; i < n; i++) {
    var x = 16 + i * gap;
    ax = xs[i] < 0 ? -xs[i] : xs[i];
    var held = keep === 1 && ax > 6;
    ctx.strokeStyle = "#b7aa9a";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x + 4, Y(0));
    ctx.lineTo(x + 4, Y(xs[i]));
    ctx.stroke();
    ctx.fillStyle = held ? "#2e7d32" : "#1f4b99";
