    ctx.fillRect(x, h * 0.1, bw - 3, i === prize ? 22 : 8);
  }
  ctx.fillStyle = "#5c564c";
  ctx.fillText("ventaja", 8, h * 0.42);
  for (i = 0; i < n; i++) {
    g = 0;
